import{QUESTOES_PAT_CARDIOVASCULAR as e,QUESTOES_PAT_DIGESTORIA as t,QUESTOES_PAT_MUSCULOESQUELETICA as n,QUESTOES_PAT_NEUROLOGICA as r,QUESTOES_PAT_RESPIRATORIA as i,QUESTOES_PAT_URINARIA as a}from"./bancoPatologiaEspecial_part1-DMXtVJ31.js";import{QUESTOES_PAT_ENDOCRINA as o,QUESTOES_PAT_HEMATOLOGICA as s,QUESTOES_PAT_HEPATICA as c,QUESTOES_PAT_OCULAR as l,QUESTOES_PAT_REPRODUTIVA as u,QUESTOES_PAT_TEGUMENTAR as d}from"./bancoPatologiaEspecial_part2-TVUoM7o0.js";var f={ENAV:{nome:`ENAV`,cor:`#1E40AF`},CESPE:{nome:`CESPE/Cebraspe`,cor:`#991B1B`},FCC:{nome:`FCC`,cor:`#166534`},VUNESP:{nome:`VUNESP`,cor:`#7C2D12`},AVAMEC:{nome:`AVAMEC`,cor:`#581C87`},CRMV:{nome:`CRMV`,cor:`#0E7490`},UFMG:{nome:`UFMG`,cor:`#4338CA`},UNESP:{nome:`UNESP`,cor:`#B45309`},USP:{nome:`USP`,cor:`#0F766E`},UFRRJ:{nome:`UFRRJ`,cor:`#BE185D`}},p={concurso:{nome:`Concurso Público`,cor:`#1E40AF`},residencia:{nome:`Residência Veterinária`,cor:`#9333EA`},enav:{nome:`ENAV`,cor:`#DC2626`},crmv:{nome:`Exame CRMV`,cor:`#0D9488`},pos:{nome:`Pós-Graduação`,cor:`#D97706`}},m={patologia_cardiovascular:{nome:`Patologia Cardiovascular`,eixo:`clin`},patologia_respiratoria:{nome:`Patologia Respiratória`,eixo:`clin`},patologia_digestoria:{nome:`Patologia Digestória`,eixo:`clin`},patologia_urinaria:{nome:`Patologia Urinária`,eixo:`clin`},patologia_neurologica:{nome:`Patologia Neurológica`,eixo:`clin`},patologia_musculoesqueletica:{nome:`Patologia Musculoesquelética`,eixo:`clin`},patologia_reprodutiva:{nome:`Patologia Reprodutiva`,eixo:`clin`},patologia_endocrina:{nome:`Patologia Endócrina`,eixo:`clin`},patologia_tegumentar:{nome:`Patologia Tegumentar`,eixo:`clin`},patologia_hepatica:{nome:`Patologia Hepática`,eixo:`clin`},patologia_hematologica:{nome:`Patologia Hematológica`,eixo:`clin`},patologia_ocular:{nome:`Patologia Ocular`,eixo:`clin`}},h=[{id:`patesp-001`,banca:`ENAV`,ano:2022,prova:`ENAV — Residência Clínica Médica 2022`,tipo:`residencia`,topico:`patologia_cardiovascular`,subtopico:`Cardiomiopatias`,dificuldade:`medio`,enunciado:`Um cão da raça Dobermann, macho, 6 anos, apresenta sinais de insuficiência cardíaca congestiva bilateral. Ao ecocardiograma, observa-se dilatação ventricular esquerda com fração de encurtamento reduzida. Qual o diagnóstico histopatológico mais provável?`,alternativas:[`Cardiomiopatia hipertrófica com hipertrofia concêntrica dos cardiomiócitos.`,`Cardiomiopatia dilatada com degeneração miocárdica e fibrose intersticial.`,`Cardiomiopatia restritiva com deposição de amiloide no miocárdio.`,`Displasia arritmogênica do ventrículo direito com substituição fibrogordurosa.`,`Estenose aórtica subvalvular com hipertrofia miocárdica concêntrica.`],resposta_correta:`B`,explicacao:`A cardiomiopatia dilatada (CMD) é a cardiopatia mais comum em Dobermanns. Histologicamente, caracteriza-se por degeneração miocárdica (cardiomiócitos com perda de estriação transversal, vacuolização citoplasmática), fibrose intersticial e necrose multifocal. Clinicamente, manifesta-se com dilatação ventricular esquerda, redução da fração de encurtamento e sinais de insuficiência cardíaca congestiva bilateral.`},{id:`patesp-002`,banca:`CESPE`,ano:2021,prova:`CESPE — Médico Veterinário IBAMA 2021`,tipo:`concurso`,topico:`patologia_cardiovascular`,subtopico:`Endocardiose`,dificuldade:`facil`,enunciado:`A endocardiose valvar é a cardiopatia mais frequente em cães de pequeno porte idosos. Sobre essa afecção, assinale a alternativa CORRETA:`,alternativas:[`Atinge preferencialmente as valvas semilunares da aorta e artéria pulmonar.`,`Caracteriza-se por espessamento mixomatoso das valvas atrioventriculares, especialmente a mitral.`,`Tem etiologia bacteriana, com formação de vegetações valvares.`,`É mais comum em cães jovens de raças grandes, como Labrador Retriever.`,`A lesão histopatológica típica é a mineralização valvar com deposição de cálcio.`],resposta_correta:`B`,explicacao:`A endocardiose valvar (doença mixomatosa degenerativa) é a cardiopatia mais comum em cães, acometendo principalmente cães de pequeno porte e idosos. Caracteriza-se por espessamento mixomatoso das cúspides valvares atrioventriculares (mitral > tricúspide), com deposição de material glicosaminoglicano na esponjosa da valva, levando a regurgitação e sopro cardíaco.`},{id:`patesp-003`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Professor Veterinária 2020`,tipo:`concurso`,topico:`patologia_cardiovascular`,subtopico:`Pericardite`,dificuldade:`dificil`,enunciado:`Um cão Golden Retriever, macho, 8 anos, apresenta distensão abdominal progressiva, turgência jugular e pulso paradoxal. À ecocardiografia, detecta-se grande volume de líquido no saco pericárdico. O líquido pericárdico obtido por centese é hemorrágico. Qual a neoplasia cardíaca primária mais frequente nessa espécie que justifica o quadro?`,alternativas:[`Hemangiossarcoma de átrio direito, com projeção pericárdica.`,`Linfoma cardíaco multicêntrico com envolvimento pericárdico.`,`Quemodectoma de corpo carotídeo com extensão cardíaca.`,`Feocromocitoma com metástases pericárdicas.`,`Osteossarcoma cardíaco primário com efusão pericárdica.`],resposta_correta:`A`,explicacao:`O hemangiossarcoma é a neoplasia cardíaca primária mais frequente em cães, localizando-se preferencialmente no átrio direito e apêndice atrial direito. Causa hemopericárdio (líquido pericárdico hemorrágico), tamponamento cardíaco e sinais de obstrução ao retorno venoso (distensão jugular, ascite, pulso paradoxal). Raças de grande porte como Golden Retrievers e Pastores Alemães são predispostas.`},{id:`patesp-004`,banca:`FCC`,ano:2019,prova:`FCC — Médico Veterinário Prefeitura SP 2019`,tipo:`concurso`,topico:`patologia_cardiovascular`,subtopico:`Miocardite`,dificuldade:`medio`,enunciado:`Sobre a miocardite em animais domésticos, é CORRETO afirmar:`,alternativas:[`A miocardite viral em cães é causada exclusivamente pelo vírus da cinomose, com tropismo exclusivo pelo sistema nervoso central.`,`A miocardite por Trypanosoma cruzi (doença de Chagas) caracteriza-se por infiltrado linfoplasmocítico e parasitismo de cardiomiócitos com formas amastigotas.`,`A miocardite supurativa bacteriana é rara em animais e ocorre apenas por contiguidade de abscessos pulmonares.`,`A miocardite eosinofílica é a forma mais comum em equinos e está associada a infecções parasitárias intestinais.`,`A miocardite granulomatosa é típica de intoxicação por monensina em bovinos, com formação de granulomas centrais.`],resposta_correta:`B`,explicacao:`A miocardite por Trypanosoma cruzi (doença de Chagas) é caracterizada histologicamente por infiltrado inflamatório linfoplasmocítico difuso no miocárdio, com parasitismo de cardiomiócitos por formas amastigotas (corpúsculos de Leishmania). Causa miocardite granulomatosa e pode levar a insuficiência cardíaca congestiva. É endêmica em regiões da América Latina, com cães como importantes reservatórios.`},{id:`patesp-005`,banca:`UFMG`,ano:2018,prova:`UFMG — Residência Patologia Animal 2018`,tipo:`residencia`,topico:`patologia_cardiovascular`,subtopico:`Aterosclerose`,dificuldade:`facil`,enunciado:`Sobre a aterosclerose em animais, assinale a alternativa INCORRETA:`,alternativas:[`É incomum em cães e gatos, mas pode ocorrer secundariamente a hipotireoidismo ou diabetes mellitus.`,`Em aves psitacídeos, é extremamente frequente e associada a dietas ricas em lipídios e deficiência em vitamina A.`,`As lesões ateroscleróticas iniciais incluem disfunção endotelial, acúmulo de lipoproteínas na íntima e recrutamento de macrófagos.`,`A aterosclerose em cavalos é descrita como complicação de parasitismo arterial por Strongylus vulgaris na artéria mesentérica cranial.`,`A aterosclerose em suínos é utilizada como modelo experimental para a doença humana, sendo rara em condições naturais nessa espécie.`],resposta_correta:`E`,explicacao:`A alternativa E está incorreta porque suínos desenvolvem aterosclerose espontaneamente de forma semelhante ao humano, sendo amplamente usados como modelo natural e experimental. A doença é frequente em suínos de idade avançada, especialmente com dietas hiperlipídicas. As demais alternativas estão corretas: aterosclerose é rara em cães/gatos (exceto secundária), comum em psitacídeos, e a arterite por Strongylus vulgaris pode levar a lesões ateroscleróticas em equinos.`},{id:`patesp-006`,banca:`UNESP`,ano:2023,prova:`UNESP — Concurso Professor Patologia 2023`,tipo:`pos`,topico:`patologia_respiratoria`,subtopico:`Pneumonia`,dificuldade:`medio`,enunciado:`Um bovino jovem apresenta febre, dispneia e tosse há 5 dias. Na necropsia, observa-se consolidação cranioventral dos pulmões com exsudato fibrinoso na superfície pleural. À histologia, há necrose de coagulação do parênquima pulmonar com trombose vascular. Qual o tipo de pneumonia mais compatível com o achado?`,alternativas:[`Pneumonia intersticial difusa com hiperplasia de pneumócitos tipo II.`,`Pneumonia fibrinosa (cruposa) com exsudato intra-alveolar fibrinoso e necrose hemorrágica.`,`Pneumonia supurativa (broncopneumonia) com infiltrado neutrofílico brônquico.`,`Pneumonia granulomatosa com formação de granulomas caseosos centrais.`,`Pneumonia eosinofílica com infiltrado eosinofílico peribronquial.`],resposta_correta:`B`,explicacao:`A pneumonia fibrinosa (cruposa) é caracterizada por consolidação difusa ou lobular, exsudato fibrinoso na superfície pleural (pleurite fibrinosa), necrose de coagulação do parênquima e trombose vascular. Em bovinos, é frequentemente associada a Mannheimia haemolytica e Pasteurella multocida, que produzem leucotoxinas causando necrose endotelial e extravasamento de fibrina. A distribuição cranioventral é típica de broncopneumonias por aspiração.`},{id:`patesp-007`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Residência Patologia 2022`,tipo:`residencia`,topico:`patologia_respiratoria`,subtopico:`Bronquite`,dificuldade:`facil`,enunciado:`A bronquite crônica em felinos domésticos está frequentemente associada a qual processo inflamatório histopatológico?`,alternativas:[`Infiltrado eosinofílico peribronquial e bronquiolar com hiperplasia de células caliciformes.`,`Infiltrado neutrofílico purulento com formação de abscessos peribrônquicos.`,`Granulomas caseosos com bacilos álcool-ácido resistentes no interior de macrófagos.`,`Fibrose intersticial difusa com metaplasia escamosa do epitélio brônquico.`,`Edema peribronquial com hemorragia alveolar e deposição de hemosiderina.`],resposta_correta:`A`,explicacao:`A bronquite crônica felina é frequentemente de natureza alérgica/asma felina, caracterizada por infiltrado inflamatório eosinofílico peribronquico e bronquiolar, hiperplasia de células caliciformes (produtoras de muco) e espessamento da membrana basal. Essa condição é a principal causa de tosse e dispneia crônica em gatos, semelhante à asma brônquica humana.`},{id:`patesp-008`,banca:`USP`,ano:2021,prova:`USP — Doutorado Patologia Comparada 2021`,tipo:`pos`,topico:`patologia_respiratoria`,subtopico:`Enfisema`,dificuldade:`dificil`,enunciado:`O enfisema pulmonar em equinos atletas é uma condição respiratória crônica importante. Sobre a fisiopatologia e histopatologia dessa condição, assinale a alternativa CORRETA:`,alternativas:[`O enfisema em cavalos é exclusivamente de causa infecciosa, causado por Streptococcus equi subsp. equi.`,`Caracteriza-se por destruição das paredes alveolares com formação de espaços aéreos anormais permanentes e hiperinsuflação pulmonar, sem fibrose significativa.`,`A lesão principal é a broncoconstrição com edema de mucosa brônquica, sem alteração do parênquima alveolar.`,`O enfisema compensatório ocorre por hiperventilação de lobos saudáveis adjacentes a áreas de consolidação pneumônica.`,`A forma bolhosa do enfisema é a mais comum em cavalos, com formação de bullas subpleurais de grande tamanho.`],resposta_correta:`B`,explicacao:`O enfisema pulmonar (DPOC/recurrent airway obstruction em cavalos) caracteriza-se pela destruição progressiva das paredes alveolares distais aos bronquíolos terminais, resultando em espaços aéreos anormalmente dilatados e permanentes. A hiperinsuflação alveolar leva ao achatamento do diafragma e limitação do fluxo aéreo expiratório. Em cavalos, a condição é de natureza alérgica/inflamatória crônica, associada a alérgenos inalados.`},{id:`patesp-009`,banca:`CRMV`,ano:2020,prova:`CRMV-SP — Prova de Títulos 2020`,tipo:`crmv`,topico:`patologia_respiratoria`,subtopico:`Edema pulmonar`,dificuldade:`facil`,enunciado:`O edema pulmonar agudo em cães pode ocorrer em diversas condições clínicas. Qual das seguintes situações NÃO é causa habitual de edema pulmonar?`,alternativas:[`Insuficiência cardíaca esquerda com elevação da pressão hidrostática capilar pulmonar.`,`Inalação de fumaça em incêndios, com lesão direta do endotélio capilar pulmonar.`,`Intoxicação por organofosforados com hipersecreção de fluido nas vias aéreas.`,`Hipertensão portal com ascite e congestão pulmonar secundária.`,`Lesão pulmonar aguda por sepse, com aumento da permeabilidade capilar pulmonar.`],resposta_correta:`D`,explicacao:`A hipertensão portal causa ascite (acúmulo de líquido na cavidade abdominal) e congestão esplâncnica, mas não edema pulmonar diretamente. O edema pulmonar ocorre por: aumento da pressão hidrostática (insuficiência cardíaca esquerda), aumento da permeabilidade capilar (lesão pulmonar aguda, sepse, inalação de fumaça) ou hipersecreção brônquica (organofosforados). A hipertensão portal desvia o fluxo para circulação colateral, não para o pulmão.`},{id:`patesp-010`,banca:`UFRRJ`,ano:2019,prova:`UFRRJ — Concurso Professor Patologia 2019`,tipo:`concurso`,topico:`patologia_respiratoria`,subtopico:`Neoplasias pulmonares`,dificuldade:`medio`,enunciado:`Qual o tumor pulmonar primário mais frequente em cães e qual sua característica histopatológica principal?`,alternativas:[`Carcinoma de células escamosas, com formação de pérolas córneas e queratinização.`,`Adenocarcinoma bronquioloalveolar, com crescimento lepídico ao longo das paredes alveolares.`,`Carcinoma de pequenas células, com células fusiformes e cromatina granular tipo "sal e pimenta".`,`Mesotelioma difuso, com proliferação de células mesoteliais sobre a pleura visceral.`,`Hemangiossarcoma pulmonar primário, com formação de espaços vasculares anastomosados.`],resposta_correta:`B`,explicacao:`O adenocarcinoma bronquioloalveolar é o tumor pulmonar primário mais frequente em cães. Histologicamente, apresenta crescimento lepídico (células neoplásicas se as paredes alveolares preservando a arquitetura), com células colunares a cuboidais formando estruturas glandulares ou papilares. Clinicamente pode ser assintomático por longo período e é frequentemente achado radiológico incidental.`},{id:`patesp-011`,banca:`CESPE`,ano:2023,prova:`CESPE — Médico Veterinário MAPA 2023`,tipo:`concurso`,topico:`patologia_digestoria`,subtopico:`Gastroenterite`,dificuldade:`facil`,enunciado:`A parvovirose canina é uma das causas mais importantes de gastroenterite em cães jovens. Sobre as lesões histopatológicas do parvovírus canino (CPV-2), assinale a alternativa CORRETA:`,alternativas:[`O CPV-2 causa necrose das criptas intestinais com depleção linfóide e encurtamento das vilosidades.`,`O CPV-2 infecta seletivamente os enterócitos do terço apical das vilosidades, preservando as criptas.`,`As lesões são predominantemente no estômago, com gastrite erosiva e ulceração da mucosa gástrica.`,`O CPV-2 causa hiperplasia das glândulas de Brunner no duodeno com metaplasia pancreática.`,`A lesão principal é a formação de granulomas transmurais no íleo e cólon.`],resposta_correta:`A`,explicacao:`O parvovírus canino (CPV-2) tem tropismo por células com alta taxa de mitose, especialmente os epitélios das criptas intestinais e linfócitos. Causa necrose dos criptócitos, levando a encurtamento ou ausência de vilosidades, atrofia da mucosa intestinal, e depleção linfoide (linfonodos mesentéricos, timo, medula óssea). As lesões mais graves ocorrem no jejuno e íleo.`},{id:`patesp-012`,banca:`VUNESP`,ano:2021,prova:`VUNESP — Concurso Veterinário Prefeitura 2021`,tipo:`concurso`,topico:`patologia_digestoria`,subtopico:`IBD`,dificuldade:`medio`,enunciado:`A doença inflamatória intestinal (IBD) em cães e gatos é caracterizada por infiltrado inflamatório crônico na mucosa intestinal. Sobre os subtipos histológicos de IBD, é CORRETO afirmar:`,alternativas:[`A enterite linfoplasmocítica é o subtipo mais comum em cães e gatos, com infiltrado de linfócitos e plasmócitos na lâmina própria.`,`A enterite eosinofílica é sempre secundária a parasitismo intestinal e nunca ocorre como condição idiopática.`,`A enterite granulomatosa é o subtipo mais frequente e caracteriza-se por granulomas não-caseosos transmurais, semelhante à doença de Crohn humana.`,`A enterite neutrofílica é a forma mais comum de IBD e está sempre associada a infecção bacteriana primária.`,`A IDB em gatos é exclusivamente de etiologia alimentar, sem componente imunomediado.`],resposta_correta:`A`,explicacao:`A enterite linfoplasmocítica é o subtipo mais comum de IBD tanto em cães quanto em gatos. Caracteriza-se por infiltrado inflamatório crônico composto predominantemente por linfócitos e plasmócitos na lâmina própria da mucosa intestinal, com graus variáveis de distorção arquitetural das vilosidades. A etiologia é multifatorial, envolvendo predisposição genética, microbioma alterado e hipersensibilidade alimentar.`},{id:`patesp-013`,banca:`ENAV`,ano:2020,prova:`ENAV — Residência Cirurgia 2020`,tipo:`enav`,topico:`patologia_digestoria`,subtopico:`Pancreatite`,dificuldade:`dificil`,enunciado:`A pancreatite aguda em cães pode evoluir para necrose pancreática extensa. Sobre a classificação e histopatologia da pancreatite em cães, assinale a alternativa CORRETA:`,alternativas:[`A pancreatite necrohemorrágica é a forma mais leve, com edema intersticial e infiltrado neutrofílico discreto.`,`A pancreatite edematosa intersticial aguda caracteriza-se por edema do estroma pancreático, infiltrado neutrofílico e necrose gordurosa peripancreática.`,`A pancreatite crônica em cães é sempre secundária a pancreatite aguda recorrente.`,`A lesão histopatológica mais precoce da pancreatite aguda é a metaplasia escamosa dos ductos pancreáticos.`,`A pancreatite autoimune é a forma mais comum em cães, com deposição de complexos imunes nas paredes dos ductos.`],resposta_correta:`B`,explicacao:`A pancreatite edematosa intersticial aguda é a forma mais comum e leve em cães, caracterizada por edema do estroma pancreático, infiltrado inflamatório neutrofílico intersticial e necrose gordurosa peripancreática (saponificação). Pode progredir para pancreatite necrohemorrágica em casos graves. A pancreatite crônica em cães pode ocorrer independentemente de episódios agudos prévios, com fibrose e atrofia acinar progressiva.`},{id:`patesp-014`,banca:`FCC`,ano:2022,prova:`FCC — Médico Veterinário UFSCar 2022`,tipo:`concurso`,topico:`patologia_digestoria`,subtopico:`Obstrução intestinal`,dificuldade:`medio`,enunciado:`A obstrução intestinal em cães por corpo estranho linear (ex.: barbante, meia) apresenta características patológicas peculiares. Qual das seguintes afirmações descreve corretamente as lesões observadas?`,alternativas:[`O corpo estranho linear causa obstrução completa anelar do intestino delgado, sem lesão da mucosa.`,`O barbante se enrola na base da língua e se estende pelo intestino delgado, causando pregueamento e perfuração mesentérica do jejuno.`,`A obstrução por corpo estranho linear causa exclusivamente lesões no cólon, com ulceração linear da mucosa colônica.`,`O corpo estranho linear permanece no estômago e causa úlceras gástricas crônicas sem progressão intestinal.`,`A obstrução linear causa dilatação uniforme de todo o intestino delgado, sem diferença entre segmentos proximal e distal.`],resposta_correta:`B`,explicacao:`Corpos estranhos lineares (barbantes, meias, fios dental) caracteristicamente se prendem na base da língua ou piloro e avançam pelo intestino delgado, causando pregueamento (plicação) do mesentério e perfuração serosa do jejuno. O intestino proximal ao ponto de ancoragem se dilata, enquanto o distal permanece normal ou colapsado. As lesões incluem úlceras lineares, perfurações e peritonite focal.`},{id:`patesp-015`,banca:`UFMG`,ano:2019,prova:`UFMG — Mestrado Patologia Animal 2019`,tipo:`pos`,topico:`patologia_digestoria`,subtopico:`Volvulo`,dificuldade:`facil`,enunciado:`Sobre a torção/vólvulo gástrico-dilatação (GDV) em cães de raças grandes, assinale a alternativa CORRETA:`,alternativas:[`A GDV é exclusiva de cães e nunca é descrita em outras espécies domésticas.`,`As lesões incluem congestão e edema da parede gástrica, necrose isquêmica da mucosa, trombose vascular e desvio de cloreto de hidrogênio para a corrente sanguínea (alcalose metabólica).`,`A lesão primária na GDV é a perfuração gástrica com peritonite química por ácido clorídrico livre na cavidade abdominal.`,`O vólvulo gástrico sempre envolve rotação de 360 graus do estômago ao redor do eixo hepatogástrico.`,`A GDV causa acidose metabólica severa pela perda de bicarbonato nas secreções gástricas.`],resposta_correta:`B`,explicacao:`Na GDV, a torção do estômago obstrui as saídas (cárdia e piloro), levando a dilatação gasosa, congestão da parede gástrica, edema, hemorragia e necrose isquêmica da mucosa por comprometimento vascular. A estase gástrica e absorção de ácido clorídrico causam hipocloremia e alcalose metabólica. Trombose intramural e perfuração são complicações tardias. O vólvulo geralmente é de 90 a 360 graus.`},{id:`patesp-016`,banca:`UNESP`,ano:2022,prova:`UNESP — Concurso Professor Veterinária 2022`,tipo:`pos`,topico:`patologia_urinaria`,subtopico:`Glomerulonefrite`,dificuldade:`dificil`,enunciado:`A glomerulonefrite membranoproliferativa em cães é frequentemente associada a depósitos imunes subendoteliais. Sobre a classificação das glomerulonefrites por imunofluorescência, qual padrão é mais compatível com nefrite lúpica (lupus eritematoso sistêmico)?`,alternativas:[`Depósitos granulares de IgG e C3 em padrão mesangial, com aspecto de "grânulos de poeira" na imunofluorescência.`,`Depósitos lineares de IgG ao longo da membrana basal glomerular, compatível com nefrite anti-MBG.`,`Depósitos granulares "em colar de pérolas" de IgG, IgA e C3 ao longo da membrana basal capilar glomerular.`,`Ausência de depósitos imunes na imunofluorescência, com achados apenas na microscopia eletrônica.`,`Depósitos exclusivos de C1q e C4 no mesângio, sem imunoglobulinas associadas.`],resposta_correta:`C`,explicacao:`A nefrite lúpica caracteriza-se por depósitos imunes granulares em padrão "em colar de pérolas" (wire-loop) na membrana basal capilar glomerular, contendo IgG, IgA, IgM e complemento (C3, C1q). Esse padrão reflete a deposição de imunocomplexos circulantes formados durante o lúpus eritematoso sistêmico. A classificação de OMS para nefrite lúpica vai de classe I (mesangial mínima) a classe VI (esclerose global).`},{id:`patesp-017`,banca:`AVAMEC`,ano:2021,prova:`AVAMEC — Residência Clínica 2021`,tipo:`residencia`,topico:`patologia_urinaria`,subtopico:`Nefrose`,dificuldade:`facil`,enunciado:`A nefrose tubular aguda em cães é causada por lesão direta das células tubulares renais. Qual das seguintes substâncias é causa clássica de nefrose tubular aguda em cães?`,alternativas:[`AINEs (anti-inflamatórios não esteroidais), especialmente o etilenoglicol (anticongelante).`,`Penicilina G cristalina, por cristalização nos túbulos renais.`,`Furosemida em doses terapêuticas, por desidratação e redução do fluxo tubular.`,`Vitamina D3 em doses profiláticas, por hipercalcemia transitória.`,`Doxorrubicina, por toxicidade dose-dependente nos podócitos glomerulares.`],resposta_correta:`A`,explicacao:`O etilenoglicol (presente em anticongelantes) é uma causa clássica de nefrose tubular aguda em cães e gatos. É metabolizado no fígado em glicolaldeído, glicólico e oxálico ácido, que causam necrose tubular aguda e cristalização de oxalato de cálcio nos túbulos renais. Os AINEs também causam nefrose tubular por redução do fluxo sanguíneo renal mediado por prostaglandinas.`},{id:`patesp-018`,banca:`USP`,ano:2020,prova:`USP — Residência Patologia 2020`,tipo:`residencia`,topico:`patologia_urinaria`,subtopico:`IRC`,dificuldade:`medio`,enunciado:`A insuficiência renal crônica (IRC) em gatos idosos está frequentemente associada a qual lesão histopatológica predominante?`,alternativas:[`Nefrite intersticial crônica com fibrose intersticial, atrofia tubular e infiltrado linfoplasmocítico.`,`Glomeruloesclerose segmentar e focal com hialinização dos glomérulos.`,`Amiloidose renal sistêmica com deposição de proteína amiloide AA nos mesângios glomerulares.`,`Nefropatia por displasia renal multicística com cistos corticais bilaterais.`,`Necrose papilar com mineralização das papilas renais bilaterais.`],resposta_correta:`A`,explicacao:`A nefrite intersticial crônica é a lesão histopatológica mais frequente na IRC felina. Caracteriza-se por fibrose intersticial progressiva, atrofia tubular, infiltrado inflamatório linfoplasmocítico intersticial e espessamento da cápsula de Bowman. A nefrose tubulointersticial crônica é a principal causa de IRC em gatos idosos, frequentemente de etiologia idiopática, mas associada a infecções renais prévias, nefrotoxinas ou nefropatia hipocalêmica.`},{id:`patesp-019`,banca:`CRMV`,ano:2018,prova:`CRMV-RJ — Prova de Títulos 2018`,tipo:`crmv`,topico:`patologia_urinaria`,subtopico:`Pielonefrite`,dificuldade:`facil`,enunciado:`A pielonefrite ascendente é uma infecção bacteriana que acomete o rim por ascensão a partir do trato urinário inferior. Sobre as lesões histopatológicas da pielonefrite aguda, é CORRETO afirmar:`,alternativas:[`A lesão característica é a formação de abscessos corticais com infiltrado neutrofílico supurativo, frequentemente dispostos em cunha.`,`A pielonefrite aguda causa exclusivamente lesões medulares, com preservação do córtex renal.`,`A lesão típica é a deposição de cristais de estruvite na pelve renal com reação gigantocelular.`,`A pielonefrite sempre cursa com formação de granulomas caseosos centrais, semelhante à tuberculose.`,`A pielonefrite aguda é caracterizada por necrose cortical difusa com hemorragia extensa.`],resposta_correta:`A`,explicacao:`A pielonefrite ascendente caracteriza-se por abscessos corticais em padrão linear ou em cunha, seguindo os ductos coletores da medula para o córtex. O infiltrado é predominantemente neutrofílico supurativo, com formação de abscessos e necrose tecidual. A infecção ascende do trato urinário inferior (cistite, uretrite) pelos ureteres até a pelve renal e parênquima, sendo Escherichia coli a bactéria mais comum.`},{id:`patesp-020`,banca:`ENAV`,ano:2023,prova:`ENAV — Residência Clínica 2023`,tipo:`residencia`,topico:`patologia_urinaria`,subtopico:`Cistite`,dificuldade:`medio`,enunciado:`A cistite em cães e gatos pode ter diversas etiologias. Sobre a cistite enfisematosa em gatos diabéticos, assinale a alternativa CORRETA:`,alternativas:[`A cistite enfisematosa é causada por infecção por bactérias produtoras de urease, como Proteus spp.`,`A cistite enfisematosa caracteriza-se por acúmulo de gás na parede da bexiga, produzido por bactérias fermentadoras de glicose em condições de hiperglicemia.`,`A cistite enfisematosa é uma condição exclusivamente alérgica, sem envolvimento bacteriano.`,`A cistite enfisematosa ocorre apenas em machos castrados, por obstrução uretral associada.`,`A cistite enfisematosa é sempre causada por Corynebacterium urealyticum, produtora de urease.`],resposta_correta:`B`,explicacao:`A cistite enfisematosa é uma condição rara mas característica de gatos (e cães) diabéticos com hiperglicemia persistente. Bactérias como Escherichia coli e Klebsiella spp. fermentam a glicose elevada na urina, produzindo gás (CO₂ e H₂) que se acumula na parede da bexiga. Radiograficamente, observa-se "bexiga em vidro fosco" pelo gás intramural. A condição é potencialmente fatal por risco de ruptura vesical.`},{id:`patesp-021`,banca:`CESPE`,ano:2022,prova:`CESPE — Médico Veterinário IBAMA 2022`,tipo:`concurso`,topico:`patologia_neurologica`,subtopico:`Encefalite`,dificuldade:`medio`,enunciado:`A encefalite por cinomose em cães é causada pelo vírus da cinomose (CDV), da família Paramyxoviridae. Sobre as lesões histopatológicas da encefalite por cinomose, assinale a alternativa CORRETA:`,alternativas:[`As lesões são exclusivamente desmielinizantes, sem componente inflamatório perivascular.`,`Caracteriza-se por encefalite não supurativa com corpúsculos de inclusão eosinofílicos intranucleares e intracitoplasmáticos em astrócitos e neurônios.`,`A lesão principal é a formação de abscessos cerebrais com infiltrado neutrofílico perivascular.`,`O CDV causa encefalite granulomatosa com formação de granulomas perivasculares no tronco encefálico.`,`A encefalite por CDV é caracterizada por hemorragia difusa no parênquima encefálico sem infiltrado inflamatório.`],resposta_correta:`B`,explicacao:`A encefalite por cinomose caracteriza-se por inflamação não supurativa (linfoplasmocítica) perivascular no sistema nervoso central, com formação de corpúsculos de inclusão eosinofílicos intranucleares e intracitoplasmáticos em astrócitos, neurônios e células ependimárias. A desmielinização é secundária à infecção viral. A leucoencefalite desmielinizante é a forma mais comum em cães adultos.`},{id:`patesp-022`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Veterinário Estado 2020`,tipo:`concurso`,topico:`patologia_neurologica`,subtopico:`Meningite`,dificuldade:`facil`,enunciado:`A meningite supurativa em neonatos de bovinos é frequentemente causada por qual agente etiológico?`,alternativas:[`Escherichia coli, com tropismo pelas meninges por disseminação hematogênica a partir de onfaloflebite.`,`Listeria monocytogenes, por contaminação alimentar com silagem de má qualidade.`,`Mycobacterium bovis, por disseminação linfóide a partir de focos pulmonares.`,`Clostridium novyi, por produção de toxinas que causam edema meningeano.`,`Histoplasma capsulatum, por inalação de conídios e disseminação hematógena ao SNC.`],resposta_correta:`A`,explicacao:`A meningite supurativa em neonatos bovinos é mais frequentemente causada por Escherichia coli, que se dissemina por via hematogênica a partir de focos infecciosos primários (onfaloflebite, septicemia). A E. coli tem tropismo pelas meninges em neonatos pela imaturidade da barreira hematoencefálica. O infiltrado é supurativo (neutrofílico) no espaço subaracnoide e leptomeníngeo.`},{id:`patesp-023`,banca:`FCC`,ano:2021,prova:`FCC — Médico Veterinário Município 2021`,tipo:`concurso`,topico:`patologia_neurologica`,subtopico:`Hidrocefalia`,dificuldade:`medio`,enunciado:`A hidrocefalia em cães de raças braquicefálicas (ex.: Chihuahua, Pequinês) é frequentemente de qual tipo?`,alternativas:[`Hidrocefalia comunicante por obstrução das granulações aracnoideas e deficiência na reabsorção de LCR.`,`Hidrocefalia obstrutiva (não comunicante) por estenose do aqueduto cerebral (mesencefálico).`,`Hidrocefalia ex vacuo por perda de parênquima cerebral secundária a traumatismo craniano.`,`Hidrocefalia normotensiva por dilatação ventricular com pressão intracraniana normal.`,`Hidrocefalia por hiperprodução de LCR por papiloma do plexo coroide.`],resposta_correta:`B`,explicacao:`A hidrocefalia em cães braquicefálicas é geralmente congênita e obstrutiva (não comunicante), causada por estenose ou atresia do aqueduto cerebral (mesencefálico). A obstrução ao fluxo de LCR nos ventrículos laterais e terceiro ventrículo causa dilatação ventricular (ventriculomegalia), compressão do parênquima cerebral e sinais neurológicos como fontanela aberta, globismo craniano e convulsões.`},{id:`patesp-024`,banca:`UNESP`,ano:2019,prova:`UNESP — Doutorado Patologia 2019`,tipo:`pos`,topico:`patologia_neurologica`,subtopico:`Epilepsia`,dificuldade:`facil`,enunciado:`Sobre a epilepsia idiopática em cães, assinale a alternativa CORRETA:`,alternativas:[`A epilepsia idiopática apresenta lesões histopatológicas características no hipocampo, com esclerose temporal mesial.`,`A epilepsia idiopática é definida como epilepsia de causa desconhecida, com exame histopatológico cerebral normal (ausência de lesões estruturais identificáveis).`,`A epilepsia idiopática em cães é sempre causada por displasia cortical focal com heterotopia de neurônios.`,`A epilepsia idiopática ocorre apenas em cães machos, por influência hormonal no limiar convulsivo.`,`A epilepsia idiopática canina é causada por deficiência de GABA por degeneração dos interneurônios inibitórios.`],resposta_correta:`B`,explicacao:`A epilepsia idiopática é definida como epilepsia genética/presumida genética, com início entre 6 meses e 6 anos, sem lesões estruturais identificáveis no exame histopatológico ou neuroimagem. O termo "idiopática" indica que não há causa estrutural ou metabólica identificável. Em cães, há predisposição racial (Golden Retriever, Pastor Alemão, Labrador, Border Collie), sugerindo base genética poligênica.`},{id:`patesp-025`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Residência Patologia 2022`,tipo:`residencia`,topico:`patologia_neurologica`,subtopico:`Neoplasias nervosas`,dificuldade:`dificil`,enunciado:`Qual o tumor intracraniano primário mais frequente em cães e qual sua característica histológica principal?`,alternativas:[`Meningioma, com crescimento dural e formação de ninhos de células meningoteliais com corpúsculos psamomatosos.`,`Astrocitoma fibrilar, com células neoplásicas fusiformes positivas para GFAP em imuno-histoquímica.`,`Oligodendroglioma, com arranjo em "ovo frito" e halo perinuclear claro ao redor das células neoplásicas.`,`Neurocitoma central, com arranjo perivascular em paliçada e rosetas de Homer-Wright.`,`Schwannoma, com padrão Antoni A (palissada nuclear) e Antoni B (tecido mixoide frouxo).`],resposta_correta:`A`,explicacao:`O meningioma é o tumor intracraniano primário mais frequente em cães (e gatos). Origina-se das células aracnoides (meningoteliais) e histologicamente apresenta células epitelioides a fusiformes dispostas em ninhos, feixes ou padrão whorled (em redemoinho), com corpúsculos psamomatosos (calcificações concêntricas) e meningoteliomas. Crescem aderidos à dura-máter e comprimem o parênquima cerebral.`},{id:`patesp-026`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Residência Cirurgia 2023`,tipo:`residencia`,topico:`patologia_musculoesqueletica`,subtopico:`Miodistrofia`,dificuldade:`medio`,enunciado:`A distrofia muscular de Golden Retrievers (GRMD) é um modelo animal para a distrofia muscular de Duchenne em humanos. Qual proteína está deficientemente expressa nessa condição?`,alternativas:[`Proteína S do sarcômero, com perda da integridade da linha Z dos miofibrilas.`,`Distrofina, uma proteína do complexo associado à membrana sarcolêmica que conecta o citoesqueleto de actina à matriz extracelular.`,`Miosina de cadeia pesada, com degeneração hialina dos sarcômeros.`,`Titina, uma proteína elástica que se estende do disco Z à linha M do sarcômero.`,`Alfa-actinina, proteína estrutural da linha Z com função de ancoragem dos filamentos finos.`],resposta_correta:`B`,explicacao:`A GRMD é causada por mutação no gene da distrofina, levando à ausência ou deficiência dessa proteína na membrana sarcolêmica. A distrofina conecta o citoesqueleto de actina F ao complexo de distroglicanas na matriz extracelular, estabilizando o sarcolema durante a contração muscular. Sua ausência causa instabilidade da membrana, influxo de cálcio, necrose muscular e fibrose progressiva.`},{id:`patesp-027`,banca:`USP`,ano:2021,prova:`USP — Concurso Professor Patologia 2021`,tipo:`pos`,topico:`patologia_musculoesqueletica`,subtopico:`Miopatia`,dificuldade:`facil`,enunciado:`A miopatia por deficiência de vitamina E e selênio em bovinos e ovinos é conhecida como:`,alternativas:[`Doença do músculo branco (distrofia muscular nutricional), caracterizada por mineralização dos miofibrilas.`,`Raquitismo, com falha na mineralização da cartilagem de crescimento.`,`Osteodistrofia fibrosa, com reabsorção óssea e deposição de tecido fibroso.`,`Mioglobinúria paralítica, com rabdomiólise aguda e mioglobinúria.`,`Tetania dos pastos, com hipomagnesemia e tremores musculares.`],resposta_correta:`A`,explicacao:`A doença do músculo branco (White Muscle Disease / Distrofia Muscular Nutricional) é causada por deficiência de vitamina E e/ou selênio, levando a estresse oxidativo e peroxidação lipídica nas membranas celulares musculares. Histologicamente, há necrose de coagulação dos miofibrilas com mineralização distrófica (depósitos basofílicos de cálcio), que confere aspecto "branco" macroscópico aos músculos afetados.`},{id:`patesp-028`,banca:`ENAV`,ano:2020,prova:`ENAV — Residência Cirurgia 2020`,tipo:`enav`,topico:`patologia_musculoesqueletica`,subtopico:`Osteossarcoma`,dificuldade:`dificil`,enunciado:`O osteossarcoma é o tumor ósseo primário mais frequente em cães de raças grandes. Sobre a classificação histológica do osteossarcoma, qual variante é a mais comum em cães?`,alternativas:[`Osteossarcoma condroblástico, com predominância de matriz cartilaginosa produzida pelas células neoplásicas.`,`Osteossarcoma osteoblástico, com produção abundante de osteoide tumoral por células neoplásicas pleomórficas.`,`Osteossarcoma fibroblástico, com células fusiformes dispostas em feixes e escassa matriz osteoide.`,`Osteossarcoma telangiectásico, com espaços vasculares dilatados e áreas extensas de hemorragia e necrose.`,`Osteossarcoma de pequenas células, com células uniformes de núcleo hipercromático e alto índice mitótico.`],resposta_correta:`B`,explicacao:`A variante osteoblástica é a mais comum de osteossarcoma em cães, caracterizada por produção abundante de osteoide tumoral (matriz osteoide/predominantemente mineralizada) por células neoplásicas pleomórficas com atipia nuclear acentuada, mitoses atípicas e células gigantes multinucleadas. As outras variantes (condroblástica, fibroblástica, telangiectásica) são menos frequentes.`},{id:`patesp-029`,banca:`CESPE`,ano:2019,prova:`CESPE — Médico Veterinário Exército 2019`,tipo:`concurso`,topico:`patologia_musculoesqueletica`,subtopico:`Condroma`,dificuldade:`facil`,enunciado:`Sobre o condroma em animais domésticos, é CORRETO afirmar:`,alternativas:[`O condroma é um tumor maligno de cartilagem com alto potencial metastático para pulmões.`,`O condroma é um tumor benigno de cartilagem hialina, frequentemente achado incidental em necropsias de cães idosos, localizado no interior de ossos (enchondroma) ou na superfície periosteal.`,`O condroma em cães sempre se origina da cartilagem articular do joelho, causando claudicação progressiva.`,`O condroma é exclusivo de equinos e não ocorre em cães, gatos ou bovinos.`,`O condroma é um tumor de células redondas com diferenciação neuroendócrina.`],resposta_correta:`B`,explicacao:`O condroma é um tumor benigno de cartilagem hialina que pode se originar no interior dos ossos (enchondroma) ou na superfície periosteal (condroma periosteal/eccondroma). É frequentemente achado incidental em necropsias de cães idosos, especialmente nas costelas e ossos longos. Diferencia-se do condrossarcoma pela ausência de atipia nuclear significativa, baixo índice mitótico e ausência de invasão óssea.`},{id:`patesp-030`,banca:`VUNESP`,ano:2018,prova:`VUNESP — Concurso Professor 2018`,tipo:`pos`,topico:`patologia_musculoesqueletica`,subtopico:`Artrite`,dificuldade:`medio`,enunciado:`A artrite reumatoide em cães é uma poliartrite erosiva imunomediada. Sobre as lesões articulares características, assinale a alternativa CORRETA:`,alternativas:[`A lesão principal é a deposição de cristais de urato nas articulações, com gota tofácea.`,`Caracteriza-se por sinovite proliferativa (pannus) com destruição da cartilagem articular e erosão óssea subcondral.`,`A artrite reumatoide causa exclusivamente dano à cartilagem hialina, sem envolvimento sinovial.`,`A lesão típica é a ossificação heterotópica das articulações com formação de osteófitos.`,`A artrite reumatoide em cães é causada por infecção bacteriana das articulações por Staphylococcus intermedius.`],resposta_correta:`B`,explicacao:`A artrite reumatoide canina caracteriza-se por sinovite proliferativa crônica com formação de pannus (tecido granulação sinovial que invade a cartilagem articular). A sinóvia se espessa com hiperplasia de sinoviócitos tipo A e B, infiltrado inflamatório linfoplasmocítico e formação de vilosidades. O pannus erode a cartilagem articular e o osso subcondral, causando erosões ósseas e destruição articular.`},{id:`patesp-031`,banca:`FCC`,ano:2023,prova:`FCC — Médico Veterinário Prefeitura 2023`,tipo:`concurso`,topico:`patologia_reprodutiva`,subtopico:`Metrite`,dificuldade:`facil`,enunciado:`A metrite aguda pós-parto em vacas é frequentemente causada por infecção polimicrobiana. Qual das seguintes bactérias é o agente mais comum na metrite aguda em bovinos?`,alternativas:[`Trueperella pyogenes, frequentemente associada a Fusobacterium necrophorum e Prevotella melaninogenica.`,`Brucella abortus, causando metrite granulomatosa com placentite necrosante.`,`Leptospira interrogans, causando metrite intersticial com nefrite tubulointersticial concomitante.`,`Mycobacterium bovis, causando metrite caseosa com granulomas uterinos.`,`Chlamydia abortus, causando metrite linfoplasmocítica com inclusões citoplasmáticas.`],resposta_correta:`A`,explicacao:`A metrite aguda pós-parto em bovinos é causada por infecção polimicrobiana, sendo Trueperella pyogenes o agente mais frequente e importante, frequentemente associado a Fusobacterium necrophorum e Prevotella melaninogenica. A T. pyogenes produz uma exotoxina (pyolysina) que causa necrose tecidual e formação de abscessos. A contaminação uterina ocorre durante o parto ou no pós-parto imediato.`},{id:`patesp-032`,banca:`ENAV`,ano:2022,prova:`ENAV — Residência Clínica 2022`,tipo:`residencia`,topico:`patologia_reprodutiva`,subtopico:`Piometra`,dificuldade:`medio`,enunciado:`A piometra em cadelas é uma condição comum em fêmeas intactas de meia-idade. Sobre a fisiopatologia e histopatologia da piometra em cães, assinale a alternativa CORRETA:`,alternativas:[`A piometra é causada exclusivamente por infecção bacteriana primária do útero, sem influência hormonal.`,`A hiperplasia endometrial cística (CEH) precede a piometra, e a progesterona exógena ou endógena é fator predisponente fundamental.`,`A piometra em cães acomete apenas cornos uterinos, preservando o corpo uterino.`,`A lesão histopatológica da piometra é sempre piogranulomatosa, com granulomas centrais contendo bactérias.`,`A piometra ocorre apenas em cadelas nulíparas, sendo rara em fêmeas com histórico de prenhez.`],resposta_correta:`B`,explicacao:`A piometra em cães é precedida pela hiperplasia endometrial cística (CEH), uma condição progesterona-dependente que ocorre após o estro. A progesterona causa hiperplasia glandular, secreção aumentada e fechamento cervical, criando ambiente propício à infecção bacteriana (principalmente E. coli). A CEH-piometra é considerada uma entidade única de progressão, com a infecção sendo secundária à estase endometrial.`},{id:`patesp-033`,banca:`UNESP`,ano:2021,prova:`UNESP — Concurso Professor 2021`,tipo:`pos`,topico:`patologia_reprodutiva`,subtopico:`Orquite`,dificuldade:`facil`,enunciado:`A orquite em cães pode ter diversas etiologias. Sobre a orquite traumática, assinale a alternativa CORRETA:`,alternativas:[`A orquite traumática é sempre bilateral e cursa com atrofia testicular irreversível imediata.`,`A orquite traumática causa hemorragia intratesticular, infiltrado inflamatório agudo e pode evoluir para abscesso e infertilidade.`,`A orquite traumática é exclusiva de bovinos e não ocorre em cães ou equinos.`,`A orquite traumática causa apenas edema escrotal, sem lesão do parênquima testicular.`,`A orquite traumática é sempre autolimitada e não requer tratamento.`],resposta_correta:`B`,explicacao:`A orquite traumática em cães (e outras espécies) resulta em hemorragia intratesticular, edema, infiltrado inflamatório agudo (neutrofílico) e necrose focal dos túbulos seminíferos. Pode evoluir para formação de abscesso, fibrose e atrofia testicular, com comprometimento da espermatogênese e infertilidade. A lesão pode ser unilateral ou bilateral, dependendo da extensão do trauma.`},{id:`patesp-034`,banca:`CRMV`,ano:2020,prova:`CRMV-MG — Prova de Títulos 2020`,tipo:`crmv`,topico:`patologia_reprodutiva`,subtopico:`Epididimite`,dificuldade:`medio`,enunciado:`A epididimite em bovinos é frequentemente associada a qual agente infeccioso de transmissão sexual?`,alternativas:[`Tritrichomonas foetus, causando epididimite granulomatosa com necrose caseosa.`,`Brucella ovis, causando epididimite crônica fibrosante com granulomas espermáticos.`,`Campylobacter fetus subsp. venerealis, causando epididimite supurativa aguda.`,`Leptospira interrogans, causando epididimite intersticial com nefrite concomitante.`,`Ureaplasma diversum, causando epididimite granulomatosa com formação de granulomas espermáticos.`],resposta_correta:`B`,explicacao:`A Brucella ovis é a principal causa de epididimite crônica em ovinos (e bovinos), causando epididimite fibrosante granulomatosa com formação de granulomas espermáticos (granulomas por extravasamento de espermatozoides no interstício). Caracteriza-se por infiltrado macrofágico e gigante ao redor de espermatozoides extravasados, com fibrose progressiva e obstrução do epidídimo.`},{id:`patesp-035`,banca:`UFRRJ`,ano:2022,prova:`UFRRJ — Concurso Professor 2022`,tipo:`concurso`,topico:`patologia_reprodutiva`,subtopico:`Neoplasias mamárias`,dificuldade:`dificil`,enunciado:`Os tumores mamários são as neoplasias mais frequentes em cadelas não castradas. Sobre a classificação histológica dos tumores mamários caninos, qual afirmação está CORRETA?`,alternativas:[`Os tumores mamários mistos (carcinoma em tumor benigno misto) são os mais frequentes em cadelas, e a maioria é maligna.`,`O carcinoma simples tubulopapilar é o tipo histológico mais frequente e mais maligno em cadelas.`,`Todos os tumores mamários caninos são benignos, exceto o carcinoma inflamatório.`,`O tumor benigno misto (adenoma em tumor misto) é o mais frequente e contém componente mioepitelial e condroide.`,`O carcinoma inflamatório mamário é o tipo mais comum e apresenta melhor prognóstico.`],resposta_correta:`D`,explicacao:`O tumor benigno misto (adenoma em tumor misto) é o tumor mamário mais frequente em cadelas, contendo epitélio glandular neoplásico e componente mesenquimal (condroide, ósseo, mioepitelial). O tumor maligno misto (carcinoma em tumor benigno misto) é a neoplasia maligna mais comum. O carcinoma inflamatório é raro mas altamente agressivo, com prognóstico reservado a mau.`},{id:`patesp-036`,banca:`AVAMEC`,ano:2023,prova:`AVAMEC — Residência Clínica 2023`,tipo:`residencia`,topico:`patologia_endocrina`,subtopico:`Diabetes`,dificuldade:`medio`,enunciado:`O diabetes mellitus em gatos está frequentemente associado a qual lesão pancreática histopatológica?`,alternativas:[`Destrução autoimune das ilhotas de Langerhans por linfócitos T citotóxicos, semelhante ao diabetes tipo 1 humano.`,`Depósito de amiloide insular (amilina/IAPP) nas ilhotas de Langerhans, com perda progressiva de células beta.`,`Hiperplasia difusa das ilhotas de Langerhans com hipertrofia de células beta e hiperinsulinismo.`,`Pancreatite supurativa aguda com destruição total do parênquima exócrino e endócrino.`,`Necrose hemorrágica das ilhotas com cetoacidose diabética fulminante.`],resposta_correta:`B`,explicacao:`O diabetes mellitus felino (tipo 2) está associado ao depósito de amilina (peptídeo amiloide insular / IAPP) nas ilhotas de Langerhans. A amilina é co-secretada com a insulina pelas células beta, e em gatos tem tendência a formar depósitos amiloides que causam destruição progressiva das células beta e redução da secreção de insulina. Esse mecanismo é similar ao diabetes tipo 2 humano.`},{id:`patesp-037`,banca:`CESPE`,ano:2021,prova:`CESPE — Médico Veterinário MAPA 2021`,tipo:`concurso`,topico:`patologia_endocrina`,subtopico:`Hipotireoidismo`,dificuldade:`facil`,enunciado:`O hipotireoidismo em cães adultos é a endocrinopatia mais comum nessa espécie. Qual a glândula mais frequentemente afetada?`,alternativas:[`Hipófise anterior, com adenoma cromófobo causando deficiência de TSH.`,`Tireoide, com tireoidite linfocítica ou atrofia idiopática como causas mais comuns de hipotireoidismo primário.`,`Hipotálamo, com deficiência de TRH causando hipotireoidismo terciário.`,`Glândulas paratireoides, com hipoparatireoidismo causando hipocalcemia.`,`Glândulas adrenais, com insuficiência adrenal causando deficiência hormonal tireoidiana.`],resposta_correta:`B`,explicacao:`O hipotireoidismo canino é quase sempre primário (95% dos casos), resultando de destruição ou disfunção da glândula tireoide. As duas principais causas são: tireoidite linfocítica (autoimune, com infiltrado linfoplasmocítico e destruição folicular) e atrofia idiopática da tireoide (degeneração folicular com substituição por tecido adiposo). O hipotireoidismo secundário (hipofisário) e terciário (hipotalâmico) são raros.`},{id:`patesp-038`,banca:`USP`,ano:2020,prova:`USP — Residência Patologia 2020`,tipo:`residencia`,topico:`patologia_endocrina`,subtopico:`Hiperadrenocorticismo`,dificuldade:`dificil`,enunciado:`O hiperadrenocorticismo (síndrome de Cushing) em cães pode ser de origem hipofisária ou adrenal. Sobre os achados histopatológicos das adrenais no hiperadrenocorticismo iatrogênico, assinale a alternativa CORRETA:`,alternativas:[`Hiperplasia bilateral do córtex adrenal, especialmente da zona fasciculada, com células ricamente eosinofílicas.`,`Atrofia bilateral do córtex adrenal, com redução da zona fasciculada e reticular, preservação da zona glomerulosa.`,`Adenoma cortical unilateral com hipersecreção de cortisol, causando atrofia da adrenal contralateral.`,`Carcinoma cortical bilateral com necrose central e metástases hepáticas.`,`Hiperplasia da medula adrenal com aumento de células cromafins e catecolaminas.`],resposta_correta:`B`,explicacao:`No hiperadrenocorticismo iatrogênico (administração prolongada de glicocorticoides exógenos), o cortisol exógeno suprime a produção de ACTH hipofisário por feedback negativo. A ausência de ACTH leva a atrofia bilateral do córtex adrenal, especialmente das zonas fasciculada e reticular (ACTH-dependentes), com relativa preservação da zona glomerulosa (angiotensina-dependente). Essa atrofia é reversível com a retirada gradual do corticoide.`},{id:`patesp-039`,banca:`VUNESP`,ano:2019,prova:`VUNESP — Concurso Professor 2019`,tipo:`pos`,topico:`patologia_endocrina`,subtopico:`Insulinoma`,dificuldade:`medio`,enunciado:`O insulinoma em cães é um tumor neuroendócrino das ilhotas pancreáticas. Sobre as características histológicas e clínicas do insulinoma canino, assinale a alternativa CORRETA:`,alternativas:[`O insulinoma canino é sempre benigno (adenoma), sem potencial metastático.`,`O insulinoma canino é frequentemente maligno (carcinoma de células beta), com metástases para linfonodos regionais e fígado, e as células neoplásicas são positivas para sinaptofisina e cromogranina A.`,`O insulinoma canino é um tumor de células alfa que secreta glucagon, causando hiperglicemia.`,`O insulinoma canino sempre se apresenta como lesão multifocal bilateral no pâncreas.`,`O insulinoma canino é exclusivo de raças grandes, como Labrador Retriever.`],resposta_correta:`B`,explicacao:`O insulinoma canino é frequentemente maligno (60-70% dos casos apresentam metástases no diagnóstico), metastatizando para linfonodos regionais, fígado e omento. Histologicamente, as células neoplásicas dispostas em ninhos, trabéculas ou arranjo acinar são positivas para imuno-histoquímica neuroendócrina: sinaptofisina, cromogranina A e insulina. Causa hipoglicemia por hiperinsulinismo.`},{id:`patesp-040`,banca:`UFMG`,ano:2018,prova:`UFMG — Concurso Professor 2018`,tipo:`concurso`,topico:`patologia_endocrina`,subtopico:`Feocromocitoma`,dificuldade:`facil`,enunciado:`O feocromocitoma em cães é um tumor da medula adrenal. Sobre as características clínicas e histopatológicas, assinale a alternativa INCORRETA:`,alternativas:[`O feocromocitoma é um tumor de células cromafins produtoras de catecolaminas (adrenalina e noradrenalina).`,`Pode causar crises hipertensivas paroxísticas, taquicardia e arritmias em cães afetados.`,`Histologicamente, apresenta células neoplásicas dispostas em ninhos (Zellballen) com citoplasma granular basófilo.`,`O feocromocitoma canino é sempre benigno, sem potencial de invasão local ou metástases.`,`O feocromocitoma pode invadir a veia cava caudal, causando obstrução ao fluxo sanguíneo.`],resposta_correta:`D`,explicacao:`A alternativa D está incorreta porque o feocromocitoma canino pode ser maligno, com invasão local de estruturas adjacentes (veia cava caudal, rim, fígado) e metástases a distância (pulmões, linfonodos). A invasão da veia cava é uma complicação importante que pode causar trombose e obstrução. Histologicamente, os tumores de células cromafins dispostos em ninhos (Zellballen) são sustentados por estroma fibrovascular.`},{id:`patesp-041`,banca:`ENAV`,ano:2023,prova:`ENAV — Residência Dermatologia 2023`,tipo:`residencia`,topico:`patologia_tegumentar`,subtopico:`Dermatite`,dificuldade:`medio`,enunciado:`A dermatite atópica em cães é uma doença inflamatória pruriginosa da pele. Sobre as lesões histopatológicas da dermatite atópica canina, assinale a alternativa CORRETA:`,alternativas:[`A lesão principal é a pustulação subcorneal com neutrófilos na camada córnea, sem infiltrado dérmico.`,`Caracteriza-se por dermatite superficial perivascular a intersticial com infiltrado linfoplasmocítico e eosinofílico, hiperplasia epidérmica e spongiose.`,`A dermatite atópica causa exclusivamente alopecia não inflamatória, sem alterações epidérmicas.`,`A lesão histopatológica é granulomatosa, com granulomas dérmicos perianexiais.`,`A dermatite atópica caracteriza-se por necrose epidérmica com formação de vesículas subepidérmicas.`],resposta_correta:`B`,explicacao:`A dermatite atópica canina apresenta histologicamente dermatite superficial perivascular a intersticial com infiltrado predominantemente linfoplasmocítico, com eosinófilos variáveis. A epidérme mostra hiperplasia (acantose), hiperqueratose orto/parqueratose e spongiose (edema intercelular dos queratinócitos). Em casos crônicos, há liquenificação (espessamento da pele) e hiperpigmentação.`},{id:`patesp-042`,banca:`VUNESP`,ano:2022,prova:`VUNESP — Concurso Veterinário 2022`,tipo:`concurso`,topico:`patologia_tegumentar`,subtopico:`Pênfigo`,dificuldade:`dificil`,enunciado:`O pênfigo vulgar em cães é uma dermatose autoimune com formação de vesículas. Sobre a localização das fendas/vesículas no pênfigo vulgar, assinale a alternativa CORRETA:`,alternativas:[`As fendas ocorrem na camada subcorneal do estrato córneo, com acúmulo de neutrófilos.`,`As fendas ocorrem na junção dermoepidérmica, com separação da epidérme da derme.`,`As fendas ocorrem intraepidérmicamente na camada espinhosa (suprabasal), com acantólise de queratinócitos.`,`As fendas ocorrem exclusivamente na derme papilar, com edema dérmico superficial.`,`As fendas ocorrem na camada basal da epidérme, com separação das células basais da membrana basal.`],resposta_correta:`C`,explicacao:`No pênfigo vulgar, os autoanticorpos (IgG) atacam as desmogleínas (adesão célula-célula) na junção das células espinhosas (camada espinhosa/suprabasal), causando acantólise (perda de adesão intercelular) e formação de vesículas intraepidérmicas suprabasais. O fundo da vesícula é formado por uma camada única de células basais ("tombstoning"). Diferencia-se do pênfigo folháceo (fenda subcorneal) e do penfigóide bolhoso (fenda subepidérmica).`},{id:`patesp-043`,banca:`FCC`,ano:2021,prova:`FCC — Médico Veterinário 2021`,tipo:`concurso`,topico:`patologia_tegumentar`,subtopico:`Linfoma cutâneo`,dificuldade:`medio`,enunciado:`O linfoma cutâneo epiteliotrópico em cães é frequentemente de qual linhagem celular?`,alternativas:[`Linfoma de células B com expressão de CD20, formando massas dérmicas nodulares.`,`Linfoma de células T com expressão de CD3, infiltrando a epiderme e anexos (epiteliotropismo).`,`Linfoma de células NK (natural killer) com expressão de CD56, sem epiteliotropismo.`,`Linfoma de células plasmáticas com secreção de imunoglobulina monoclonal.`,`Linfoma de células dendríticas foliculares com formação de centros germinativos dérmicos.`],resposta_correta:`B`,explicacao:`O linfoma cutâneo epiteliotrópico em cães é predominantemente de linhagem T, com expressão de CD3 em imuno-histoquímica. A característica principal é o epiteliotropismo: infiltrado de linfócitos neoplásicos dentro da epiderme, folículos pilosos e glândulas sebáceas. Clinicamente se apresenta como placas eritematosas, descamativas, que podem evoluir para tumores. A micose fungoide é a forma mais comum de linfoma cutâneo T em cães.`},{id:`patesp-044`,banca:`UNESP`,ano:2020,prova:`UNESP — Residência Patologia 2020`,tipo:`residencia`,topico:`patologia_tegumentar`,subtopico:`Mastocitoma`,dificuldade:`facil`,enunciado:`O mastocitoma cutâneo é o tumor cutâneo mais frequente em cães. Sobre o sistema de grading histológico de Patnaik, qual afirmação está CORRETA?`,alternativas:[`O grau I (bem diferenciado) tem pior prognóstico, com alta taxa de metástases.`,`O grau II (intermediário) é o mais frequente e tem prognóstico variável, com metástases em 15-20% dos casos.`,`O grau III (indiferenciado) é o menos frequente e apresenta o melhor prognóstico.`,`O grading de Patnaik avalia exclusivamente o tamanho tumoral, sem considerar a diferenciação celular.`,`Todos os mastocitomas caninos são benignos (grau I) e nunca metastatizam.`],resposta_correta:`B`,explicacao:`O sistema de grading de Patnaik classifica os mastocitomas em: Grau I (bem diferenciado, bom prognóstico, baixo risco de metástases), Grau II (intermediário, o mais frequente, com metástases em 15-20% dos casos) e Grau III (indiferenciado, pior prognóstico, alto risco de metástases e recorrência). A classificação avalia diferenciação celular, índice mitótico, celularidade e invasão tecidual.`},{id:`patesp-045`,banca:`UFRRJ`,ano:2019,prova:`UFRRJ — Doutorado Patologia 2019`,tipo:`pos`,topico:`patologia_tegumentar`,subtopico:`Melanoma`,dificuldade:`dificil`,enunciado:`O melanoma oral em cães é a segunda neoplasia oral mais frequente e frequentemente maligno. Sobre os fatores histopatológicos preditivos de comportamento biológico, qual achado indica MELHOR prognóstico?`,alternativas:[`Melanoma amelanótico com alto índice mitótico e necrose central extensa.`,`Melanoma com baixo índice mitótico (<3 mitoses por 10 campos de grande aumento), margens cirúrgicas livres e ausência de ulceração.`,`Melanoma com metástases para linfonodos regionais e pulmões no momento do diagnóstico.`,`Melanoma com invasão óssea mandibular e ulceração extensa da mucosa oral.`,`Melanoma com diferenciação neuroendócrina e produção de catecolaminas.`],resposta_correta:`B`,explicacao:`Os fatores prognósticos favoráveis no melanoma oral canino incluem: baixo índice mitótico (<3 mitoses/10 CGA), margens cirúrgicas livres, ausência de ulceração, ausência de metástases, grau de diferenciação preservado e localização labial (melhor prognóstico que oral). Os melanomas amelanóticos geralmente têm pior prognóstico por dificuldade de diagnóstico precoce e maior agressividade biológica.`},{id:`patesp-046`,banca:`CESPE`,ano:2023,prova:`CESPE — Médico Veterinário Prefeitura 2023`,tipo:`concurso`,topico:`patologia_hepatica`,subtopico:`Hepatite`,dificuldade:`medio`,enunciado:`A hepatite crônica em cães cobre uma variedade de condições com etiologias diferentes. Sobre a hepatite crônica associada a acúmulo de cobre em cães, qual raça é classicamente predisposta?`,alternativas:[`Labrador Retriever, por defeito na excreção biliar de cobre (hepatopatia por cobre associada ao Lab).`,`Pastor Alemão, por deficiência de ceruloplasmina (análogo à doença de Wilson humana).`,`Poodle Miniatura, por absorção intestinal aumentada de cobre.`,`Bulldog Inglês, por defeito no transportador ATP7B hepático.`,`Dachshund, por deposição secundária de cobre em hepatite infecciosa canina.`],resposta_correta:`A`,explicacao:`O Labrador Retriever é a raça classicamente predisposta à hepatopatia por acúmulo de cobre, com defeito na excreção biliar de cobre (gene COMMD1/ATP7A). Os cães afetados acumulam cobre nos hepatócitos, causando estresse oxidativo, necrose hepatocelular e hepatite crônica progressiva. O Bedlington Terrier também é classicamente predisposto (deficiência de COMMD1), mas a pergunta foca no Labrador.`},{id:`patesp-047`,banca:`ENAV`,ano:2021,prova:`ENAV — Residência Clínica 2021`,tipo:`residencia`,topico:`patologia_hepatica`,subtopico:`Lipidose hepática`,dificuldade:`facil`,enunciado:`A lipidose hepática felina é uma hepatopatia grave e potencialmente reversível. Sobre as lesões histopatológicas características, assinale a alternativa CORRETA:`,alternativas:[`Os hepatócitos apresentam vacuolização citoplasmática fina e difusa (microvesicular), com núcleo central.`,`Os hepatócitos apresentam vacuolização citoplasmática volumosa (macrovesicular) com deslocamento periférico do núcleo, por acúmulo de triglicerídeos.`,`A lesão principal é a necrose de coagulação centrolobular com infiltrado neutrofílico.`,`A lipidose hepática felina causa fibrose portal extensa com formação de septos fibrosos.`,`A lesão característica é a presença de corpúsculos de Mallory no citoplasma dos hepatócitos.`],resposta_correta:`B`,explicacao:`A lipidose hepática felina caracteriza-se por acúmulo maciço de triglicerídeos no citoplasma dos hepatócitos, formando grandes vacúolos lipídicos (macrovesicular) que deslocam o núcleo para a periferia celular. Os hepatócitos aparecem "em anel de sinete" na histologia. Macroscopicamente, o fígado é amarelo, friável e aumentado. É frequentemente secundária a anorexia prolongada em gatos obesos, mobilização excessiva de gordura corporal.`},{id:`patesp-048`,banca:`USP`,ano:2022,prova:`USP — Residência Patologia 2022`,tipo:`residencia`,topico:`patologia_hepatica`,subtopico:`Cirrose`,dificuldade:`dificil`,enunciado:`A cirrose hepática é o estágio final de hepatopatias crônicas. Sobre as características morfológicas da cirrose em cães, qual afirmação está CORRETA?`,alternativas:[`A cirrose hepática caracteriza-se por fibrose difusa com regeneração nodular dos hepatócitos, destruição da arquitetura lobular normal e shunts vasculares intra-hepáticos.`,`A cirrose hepática é exclusivamente de etiologia alcoólica, como em humanos.`,`A cirrose causa sempre hepatomegalia, com fígado aumentado de volume e de consistência firme.`,`Na cirrose, os nódulos de regeneração são sempre neoplásicos e representam carcinoma hepatocelular.`,`A cirrose hepática em cães é sempre causada por infecção viral, sem outras etiologias possíveis.`],resposta_correta:`A`,explicacao:`A cirrose hepática é definida por: (1) fibrose difusa que conecta tratos portais entre si e com as veias centrais (septos fibrosos), (2) regeneração nodular dos hepatócitos com perda da arquitetura lobular normal, e (3) shunts vasculares intra-hepáticos (comunicação anormal artério-portal). Macroscopicamente, o fígado pode estar aumentado (cirrose em estágio inicial) ou reduzido (cirrose avançada). As causas incluem hepatite crônica, toxicoses, lipidose crônica.`},{id:`patesp-049`,banca:`CRMV`,ano:2021,prova:`CRMV-SP — Prova de Títulos 2021`,tipo:`crmv`,topico:`patologia_hepatica`,subtopico:`CIVD hepática`,dificuldade:`medio`,enunciado:`A coagulação intravascular disseminada (CIVD) pode ocorrer secundariamente a diversas hepatopatias. Sobre o papel do fígado na CIVD, assinale a alternativa CORRETA:`,alternativas:[`O fígado é responsável exclusivamente pela produção de fatores pró-coagulantes, sem papel na anticoagulação.`,`Na insuficiência hepática aguda, há redução da síntese de antitrombina III, proteína C e proteína S, favorecendo a CIVD.`,`A CIVD hepática ocorre exclusivamente em quadros de lipidose hepática felina.`,`O fígado não participa da CIVD, que é causada exclusivamente por fatores extra-hepáticos.`,`A CIVD hepática é sempre causada por trombose da veia porta, com isquemia hepática difusa.`],resposta_correta:`B`,explicacao:`O fígado produz tanto fatores pró-coagulantes (fibrinogênio, fatores II, V, VII, IX, X) quanto anticoagulantes (antitrombina III, proteína C, proteína S). Na insuficiência hepática aguda, a produção de anticoagulantes naturais é mais afetada que a de pró-coagulantes, criando estado pró-trombótico que favorece a CIVD. Além disso, a lesão hepatocelular libera fatores teciduais que ativam a cascata de coagulação.`},{id:`patesp-050`,banca:`UFMG`,ano:2020,prova:`UFMG — Concurso Professor 2020`,tipo:`concurso`,topico:`patologia_hepatica`,subtopico:`Neoplasias hepáticas`,dificuldade:`facil`,enunciado:`Qual o tumor hepático primário mais frequente em cães?`,alternativas:[`Hepatocarcinoma (carcinoma hepatocelular), originado dos hepatócitos.`,`Colangiocarcinoma (carcinoma de vias biliares), originado do epitélio biliar.`,`Hemangiossarcoma hepático, originado do endotélio sinusoidal.`,`Linfoma hepático, com infiltrado neoplásico difuso no parênquima.`,`Carcinoma de células hepáticas misto, com diferenciação hepatocelular e biliar.`],resposta_correta:`A`,explicacao:`O hepatocarcinoma (carcinoma hepatocelular) é o tumor hepático primário mais frequente em cães. Origina-se dos hepatócitos e histologicamente pode apresentar padrão trabecular (células dispostas em trabéculas de 2-3 células de espessura), acinar ou sólido. Frequentemente é achado incidental em necropsias de cães idosos, podendo ser único (nódulo massivo) ou multifocal.`},{id:`patesp-051`,banca:`VUNESP`,ano:2023,prova:`VUNESP — Concurso Veterinário 2023`,tipo:`concurso`,topico:`patologia_hematologica`,subtopico:`Anemias`,dificuldade:`medio`,enunciado:`A anemia hemolítica autoimune (AHAI) em cães é uma causa importante de anemia regenerativa. Sobre os achados histopatológicos no baço e medula óssea na AHAI, assinale a alternativa CORRETA:`,alternativas:[`O baço mostra atrofia folicular com depleção linfóide e a medula óssea é hipocelular.`,`O baço mostra hematopoese extramedular e a medula óssea é hiperplásica eritroide (eritroide:mieloide aumentada).`,`O baço é normal e a medula óssea mostra aplasia eritroide pura.`,`O baço mostra infartos hemorrágicos difusos e a medula óssea é necrótica.`,`O baço mostra deposição de hemosiderina exclusivamente na polpa vermelha, sem hiperplasia.`],resposta_correta:`B`,explicacao:`Na anemia hemolítica autoimune, a destruição de eritrócitos mediada por anticorpos ocorre principalmente no baço (hemólise extravascular), levando a hiperplasia da polpa vermelha e hematopoese extramedular compensatória. A medula óssea responde com hiperplasia eritroide intensa (eritropoese compensatória), aumentando a proporção eritroide:mieloide. Esplenomegalia e icterícia são achados macroscópicos comuns.`},{id:`patesp-052`,banca:`ENAV`,ano:2022,prova:`ENAV — Residência Clínica 2022`,tipo:`enav`,topico:`patologia_hematologica`,subtopico:`Leucemias`,dificuldade:`dificil`,enunciado:`A leucemia linfocítica crônica (LLC) em cães é uma neoplasia de linfócitos maduros. Sobre os critérios diagnósticos e achados histopatológicos da LLC canina, qual afirmação está CORRETA?`,alternativas:[`A LLC canina apresenta linfonodos aumentados com preservação da arquitetura folicular e hiperplasia de centros germinativos.`,`A LLC canina é caracterizada por linfocitose periférica persistente (>10.000/µL) com linfócitos pequenos maduros, e infiltrado difuso no parênquima de linfonodos, baço e medula óssea com destruição da arquitetura.`,`A LLC canina sempre apresenta blastos periféricos com nucléolos proeminentes.`,`A LLC canina é exclusiva de cães jovens (<2 anos) e está associada a infecção pelo vírus da cinomose.`,`A LLC canina é sempre causada por translocação cromossômica BCR-ABL (cromossomo Philadelphia).`],resposta_correta:`B`,explicacao:`A leucemia linfocítica crônica canina é caracterizada por linfocitose periférica persistente (>10.000/µL) com linfócitos pequenos maduros de morfologia normal. Os linfonodos mostram infiltrado difuso de linfócitos neoplásicos com destruição da arquitetura (perda de diferenciação cortical-medular, centros germinativos obscurecidos). O baço e medula óssea também são infiltrados. É mais comum em cães de meia-idade a idosos.`},{id:`patesp-053`,banca:`FCC`,ano:2020,prova:`FCC — Médico Veterinário 2020`,tipo:`concurso`,topico:`patologia_hematologica`,subtopico:`Trombocitopenia`,dificuldade:`facil`,enunciado:`A trombocitopenia imunomediada primária (púrpura trombocitopênica imune / PTI) em cães é causada por qual mecanismo?`,alternativas:[`Produção reduzida de plaquetas por insuficiência medular (megacariocitopenia).`,`Destrução periférica de plaquetas por anticorpos antiplaqueta (IgG), com fagocitose pelo sistema mononuclear fagocitário.`,`Perda de plaquetas por hemorragia gastrointestinal crônica.`,`Sequestração esplênica de plaquetas por esplenomegalia congestiva.`,`Consumo de plaquetas por CIVD secundária a sepse bacteriana.`],resposta_correta:`B`,explicacao:`A trombocitopenia imunomediada (PTI) ocorre por produção de autoanticorpos (IgG) contra antígenos plaquetários de superfície (GP IIb/IIIa), levando à opsonização e fagocitose das plaquetas pelo sistema mononuclear fagocitário (principalmente baço e fígado). Clinicamente causa petéquias, equimoses e hemorragias mucosas. Pode ser primária (idiopática) ou secundária a lúpus, linfoma ou drogas.`},{id:`patesp-054`,banca:`UNESP`,ano:2019,prova:`UNESP — Residência Patologia 2019`,tipo:`residencia`,topico:`patologia_hematologica`,subtopico:`Coagulopatias`,dificuldade:`medio`,enunciado:`A hemofilia A (deficiência do fator VIII de coagulação) é a coagulopatia hereditária mais comum em cães. Sobre as características dessa condição, assinale a alternativa CORRETA:`,alternativas:[`A hemofilia A é autossômica recessiva, afetando igualmente machos e fêmeas.`,`A hemofilia A é ligada ao cromossomo X, manifestando-se clinicamente em machos hemizigotos, enquanto fêmeas heterozigotas são portadoras assintomáticas.`,`A hemofilia A é causada por deficiência de vitamina K, com redução de todos os fatores dependentes de vitamina K.`,`A hemofilia A sempre se manifesta ao nascimento, com hemorragia umbilical extensa.`,`A hemofilia A em cães é exclusiva da raça Pastor Alemão.`],resposta_correta:`B`,explicacao:`A hemofilia A é uma coagulopatia hereditária ligada ao X, causada por deficiência quantitativa ou qualitativa do fator VIII. Machos hemizigotos (XhY) manifestam a doença clinicamente, enquanto fêmeas heterozigotas (XHXh) são portadoras assintomáticas. Afeta diversas raças caninas (Labrador, Pastor Alemão, Golden Retriever). Clinicamente causa hemartrose, hematomas musculares e hemorragias pós-cirúrgicas.`},{id:`patesp-055`,banca:`AVAMEC`,ano:2022,prova:`AVAMEC — Residência Oftalmologia 2022`,tipo:`residencia`,topico:`patologia_ocular`,subtopico:`Catarata`,dificuldade:`facil`,enunciado:`A catarata em cães é a opacificação do cristalino. Sobre as causas de catarata em cães, qual afirmação está CORRETA?`,alternativas:[`A catarata em cães é sempre congênita e não pode ocorrer em animais adultos.`,`A catarata senil é a forma mais comum em cães idosos, causada por desidratação e desnaturação das proteínas cristalinianas (cristalinas).`,`A catarata diabética em cães ocorre por hiperglicemia crônica, com conversão de glicose em sorbitol via poliol, causando edema das fibras do cristalino.`,`A catarata traumática ocorre apenas por perfuração do globo ocular, sem opacificação tardia.`,`A catarata em cães é sempre secundária a uveíte anterior.`],resposta_correta:`C`,explicacao:`A catarata diabética em cães ocorre pela via do poliol: a hiperglicemia crônica leva à conversão de glicose em sorbitol pela aldose redutase nas fibras do cristalino. O sorbitol é um poliol osmoticamente ativo que retém água, causando edema das fibras cristalinianas e opacificação progressiva. É uma das complicações mais dramáticas do diabetes mellitus canino, podendo levar à catarata madura em semanas.`},{id:`patesp-056`,banca:`CESPE`,ano:2021,prova:`CESPE — Médico Veterinário 2021`,tipo:`concurso`,topico:`patologia_ocular`,subtopico:`Glaucoma`,dificuldade:`medio`,enunciado:`O glaucoma em cães é uma neuropatia óptica causada por pressão intraocular elevada. Sobre as lesões histopatológicas oculares no glaucoma crônico canino, assinale a alternativa CORRETA:`,alternativas:[`O glaucoma causa exclusivamente lesões no cristalino, com catarata secundária.`,`O glaucoma crônico causa degeneração das células ganglionares da retina, atrofia do nervo óptico e escleral estafiloma.`,`O glaucoma afeta exclusivamente a córnea, com edema corneal permanente.`,`O glaucoma causa hiperplasia do corpo ciliar com produção excessiva de humor aquoso.`,`O glaucoma em cães sempre ocorre por fechamento angular primário, sem outras formas.`],resposta_correta:`B`,explicacao:`No glaucoma crônico, a pressão intraocular elevada causa: (1) degeneração e perda das células ganglionares da retina (camada de células ganglionares adelgaçada), (2) atrofia do nervo óptico com escavação papilar (aumento da escavação do disco óptico), (3) degeneração da retina, e (4) escleral estafiloma (protrusão da esclera). A córnea também pode apresentar edema e neovascularização.`},{id:`patesp-057`,banca:`USP`,ano:2023,prova:`USP — Doutorado Patologia 2023`,tipo:`pos`,topico:`patologia_ocular`,subtopico:`Uveíte`,dificuldade:`dificil`,enunciado:`A uveíte anterior em cães pode ter diversas etiologias. Sobre a uveíte granulomatosa lenticular (facocítica), qual mecanismo é responsável pela inflamação?`,alternativas:[`Infecção bacteriana do cristalino por Staphylococcus, com formação de abscesso intralenticular.`,`Reação inflamatória ao extravasamento de proteínas cristalinianas através de uma cápsula do cristalino rompida ou permeável.`,`Deposição de imunocomplexos na úvea anterior, secundária a infecção sistêmica por Leishmania.`,`Reação autoimune contra antígenos uveais, desencadeada por vacinação.`,`Invasão neoplásica do trato uveal por melanoma difuso.`],resposta_correta:`B`,explicacao:`A uveíte facocítica (lenticular) ocorre quando proteínas do cristalino (cristalinas) extravasam por cápsula rompida (trauma, catarata matura) ou permeável, desencadeando reação inflamatória granulomatosa no segmento anterior. As proteínas cristalinianas são reconhecidas como antígenos estranhos pelo sistema imune (o cristalino é um órgão imunologicamente privilegiado), causando uveíte anterior granulomatosa com células epitelioides e gigantes.`},{id:`patesp-058`,banca:`VUNESP`,ano:2020,prova:`VUNESP — Concurso Professor 2020`,tipo:`pos`,topico:`patologia_ocular`,subtopico:`Ceratite`,dificuldade:`facil`,enunciado:`A ceratite ulcerativa em cães pode ser causada por diversas etiologias. Sobre a ceratite ulcerativa por exposição (ceratite por lagoftalmia), qual afirmação está CORRETA?`,alternativas:[`A ceratite por exposição ocorre apenas em gatos, por infecção viral por herpesvírus felino.`,`A ceratite por exposição é causada por fechamento incompleto das pálpebras (lagoftalmia), com secamento da córnea e ulceração epitelial.`,`A ceratite por exposição é sempre causada por corpo estranho corneal.`,`A ceratite por exposição ocorre apenas em cães braquicefálicos e não em outras raças.`,`A ceratite por exposição é causada exclusivamente por deficiência de vitamina A.`],resposta_correta:`B`,explicacao:`A ceratite por exposição (ceratite de exposição) ocorre quando as pálpebras não se fecham completamente durante o sono ou piscamento (lagoftalmia), expondo a córnea ao ar e causando secamento. É comum em cães braquicefálicos (exoftalmia), paralisia do nervo facial (VII) e cicatrizes palpebrais. A úlcera de exposição tipicamente afeta a região corneal ventromedial, mais exposta.`},{id:`patesp-059`,banca:`UFRRJ`,ano:2021,prova:`UFRRJ — Residência Patologia 2021`,tipo:`residencia`,topico:`patologia_ocular`,subtopico:`Descolamento de retina`,dificuldade:`medio`,enunciado:`O descolamento de retina em cães pode ocorrer por diferentes mecanismos. Sobre o descolamento de retina em cães diabéticos, qual é o mecanismo principal?`,alternativas:[`Descolamento regmatogênico por rasgo retiniano causado por trauma ocular.`,`Descolamento tracional por membrana fibrovascular pré-retiniana, secundário a retinopatia diabética proliferativa.`,`Descolamento exsudativo por uveíte posterior com acúmulo de líquido sub-retiniano.`,`Descolamento por degeneração vitreorretiniana hereditária, como no Collie.`,`Descolamento por hipertensão sistêmica com hemorragia sub-retiniana.`],resposta_correta:`B`,explicacao:`Em cães diabéticos, a hiperglicemia crônica causa retinopatia diabética com neovascularização retiniana (proliferação de novos vasos a partir da retina). Esses vasos frágeis sangram, causando hemorragia vítrea e formação de membranas fibrovascular pré-retinianas. A contração dessas membranas traciona a retina, causando descolamento tracional. É mais comum em cães com diabetes mal controlado de longa duração.`},{id:`patesp-060`,banca:`ENAV`,ano:2024,prova:`ENAV — Residência Clínica 2024`,tipo:`residencia`,topico:`patologia_hematologica`,subtopico:`Hemoparasitoses`,dificuldade:`dificil`,enunciado:`A babesiose canina (Babesia canis/vogeli) é uma importante hemoparasitose. Sobre os mecanismos de anemia na babesiose, assinale a alternativa CORRETA:`,alternativas:[`A anemia na babesiose é exclusivamente hemodilucional, por retenção hídrica.`,`A babesiose causa anemia hemolítica extravascular por fagocitose de eritrócitos parasitados pelo sistema reticuloendotelial, e hemólise intravascular mediada por complemento.`,`A anemia na babesiose é causada por supressão medular direta pelo parasita, sem hemólise periférica.`,`A babesiose causa anemia ferropriva por perda crônica de ferro nas fezes.`,`A anemia na babesiose é exclusivamente por deficiência de vitamina B12 e folato.`],resposta_correta:`B`,explicacao:`A babesiose canina causa anemia hemolítica por dois mecanismos: (1) hemólise extravascular — eritrócitos parasitados são reconhecidos e fagocitados pelo sistema reticuloendotelial (baço, fígado); (2) hemólise intravascular — ativação do complemento e formação de complexos imunes na membrana dos eritrócitos, com liberação de hemoglobina na corrente sanguínea. A anemia é regenerativa, com reticulocitose e spherocitose.`},...e,...i,...t,...a,...r,...n,...u,...o,...d,...c,...s,...l].filter(Boolean),g={total_questoes:h.length,por_banca:Object.keys(f).reduce((e,t)=>(e[t]=h.filter(e=>e.banca===t).length,e),{}),por_topico:Object.keys(m).reduce((e,t)=>(e[t]=h.filter(e=>e.topico===t).length,e),{}),por_dificuldade:{facil:h.filter(e=>e.dificuldade===`facil`).length,medio:h.filter(e=>e.dificuldade===`medio`).length,dificil:h.filter(e=>e.dificuldade===`dificil`).length},por_tipo:Object.keys(p).reduce((e,t)=>(e[t]=h.filter(e=>e.tipo===t).length,e),{}),por_ano:h.reduce((e,t)=>(e[t.ano]=(e[t.ano]||0)+1,e),{})};export{f as BANCAS,g as ESTATISTICAS_BANCO,h as QUESTOES_PATOLOGIA_ESPECIAL,p as TIPOS_PROVA,m as TOPICOS_PATOLOGIA_ESPECIAL};